package org.sleepwell.app;
import android.app.Activity;import android.os.Bundle;import android.widget.LinearLayout;import java.util.*;import java.util.concurrent.*;
/** Read-only calculation refreshed after real record/rating/dated-goal edits. */
public final class RecordedNightScoreActivity extends Activity {
 private final ExecutorService worker=Executors.newSingleThreadExecutor();private long id;private int generation;private RecordedNightScore score;private String error="";private boolean loading;
 @Override public void onCreate(Bundle saved){super.onCreate(saved);RecordUi.review(this);id=getIntent().getLongExtra("record",0);render();}
 @Override protected void onResume(){super.onResume();load();}
 private void load(){int request=++generation;loading=true;error="";render();Records.Factory factory=Records.factory;SleepPlans.Repository plans=SleepPlans.repository(this);worker.execute(()->{try(Store store=factory.open(getApplicationContext())){if(store.rows("SELECT COUNT(*) AS n FROM sessions").get(0).optLong("n")>3000||store.rows("SELECT COUNT(*) AS n FROM tracking_pauses").get(0).optLong("n")>20000)throw new IllegalStateException("This history is too large for this calculation. Your records are kept.");List<RecordEntry> records=Records.all(store);RecordEntry selected=null;for(RecordEntry r:records)if(r.id==id){selected=r;break;}if(selected==null)throw new IllegalArgumentException("This completed record is no longer available.");List<GoalCommitment> goals;try{goals=plans.goals();}catch(RuntimeException unavailable){goals=null;}RecordedNightScore result=new RecordedNightScore(selected,records,goals,System.currentTimeMillis());runOnUiThread(()->{if(isDestroyed()||generation!=request)return;score=result;loading=false;render();});}catch(Exception failure){String message=failure instanceof IllegalArgumentException||failure instanceof IllegalStateException?failure.getMessage():"The saved recording could not be read. Your records are kept.";runOnUiThread(()->{if(isDestroyed()||generation!=request)return;loading=false;error=message==null?"Recorded score unavailable.":message;render();});}});}
 private void render(){LinearLayout body=Design.page(this,false,null,n->{});RecordUi.label(this,body);RecordUi.header(body,"Recorded night score",this::finish);Design.space(body,12);if(!error.isEmpty()){Design.text(body,error,15,500,Design.BROWN);Design.button(body,"Try again",true,this::load);return;}if(score==null){Design.text(body,"Reading saved inputs…",14,400,Design.MUTED);return;}Design.text(body,RecordUi.date(score.record.edit.end,score.record.zone()),14,400,Design.MUTED);Design.space(body,12);Design.text(body,score.total==null?"Unavailable":RecordedNightScore.number(score.total)+" / 100",38,700,Design.INK);Design.text(body,score.available+" of "+score.dimensions.size()+" inputs available",13,500,Design.MUTED);if(score.total==null)Design.text(body,score.unavailable.isEmpty()?"At least two available inputs are required. Missing values are never scored as zero.":score.unavailable,14,400,Design.MUTED);if(loading)Design.text(body,"Updating saved inputs…",12,400,Design.MUTED);Design.space(body,12);Design.text(body,"Original descriptive score, not a health, recovery, diagnosis or validated sleep-stage measurement.",14,500,Design.BROWN);Design.space(body,8);Design.text(body,"Available dimensions have equal weight: score = their sum ÷ their count. Missing inputs are omitted and weights are renormalized. A higher number only means closer agreement with these stated inputs.",13,400,Design.MUTED);
  for(RecordedNightScore.Dimension d:score.dimensions){RecordUi.heading(body,d.title);Design.text(body,d.value==null?"Unavailable":RecordedNightScore.number(d.value)+" / 100",23,600,Design.INK);if(!d.inputs.isEmpty())Design.text(body,d.inputs,13,400,Design.MUTED);if(d.value==null)Design.text(body,d.missing,13,500,Design.BROWN);Design.space(body,5);Design.text(body,d.formula,12,400,Design.MUTED);Design.space(body,8);Design.line(body);}
  Design.space(body,12);Design.text(body,"Recording can include unmarked awake time and missing sensor intervals. Continuity describes saved coverage, not sleep efficiency. No stages, heart rate, breathing, age norms or proprietary score are used. Scores with different available inputs are not directly comparable.",12,400,Design.MUTED);Design.button(body,"Edit period or rested rating",true,()->startActivity(RecordUi.intent(this,RecordEditorActivity.class).putExtra("record",id)));Design.button(body,"Review awake estimates",false,()->startActivity(RecordUi.intent(this,AwakeReviewActivity.class).putExtra("record",id)));Design.button(body,"Review dated goals",false,()->startActivity(RecordUi.intent(this,GoalBankActivity.class)));Design.button(body,"Recalculate",false,this::load);
 }
 @Override protected void onDestroy(){generation++;worker.shutdownNow();super.onDestroy();}
 @Override public void onWindowFocusChanged(boolean focus){super.onWindowFocusChanged(focus);if(focus)RecordUi.lightBars(this);}
}
